contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address log) public payable {
        uint beforeEther = address(c).balance;
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool revertedBeforeInit;
        c.SetLogFile(log); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedBeforeInit = true;
        } else {
            revertedBeforeInit = false;
        }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedAfterInit;
        c.SetLogFile(log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            revertedAfterInit = true;
        } else {
            revertedAfterInit = false;
        }

        assert(!revertedBeforeInit && revertedAfterInit && address(c).balance == beforeEther && c.balances(address(this)) == beforeBal);
    }

    receive() external payable {}
}

